# owner: platform
import unittest

from hourglass.timesheet import timesheet_rows
from hourglass.models import Shift, Span


def _shift(worker, start, end):
    return Shift(worker, "mon", Span(start, end))


class TimesheetTests(unittest.TestCase):
    # ---
    def test_rows_busiest_first(self):
        rows = timesheet_rows([
            _shift("Ana", 540, 600),
            _shift("Bo", 540, 690),
            _shift("Ana", 700, 760)
        ])
        self.assertEqual(rows, [
            "Bo: 1 shifts, 2.5 h",
            "Ana: 2 shifts, 2.0 h"
        ])

    # ---
    def test_empty_raises(self):
        with self.assertRaises(ValueError):
            timesheet_rows([])

    # ---
    def test_blank_worker_raises(self):
        with self.assertRaises(ValueError):
            timesheet_rows([_shift("  ", 540, 600)])
